/*
    Release unused space at the end of data files to the OS
*/
DECLARE @SQL NVARCHAR(250) = '
BEGIN TRY 
  DBCC SHRINKFILE (@1, TRUNCATEONLY);
  WAITFOR DELAY ''00:00:10'';
END TRY
BEGIN CATCH
END CATCH
';
DECLARE @Script NVARCHAR(max) = 'USE [FastwayDW];'

SELECT @Script = @Script + REPLACE(@SQL,'@1',FileId)
FROM (
  SELECT df.file_id as FileId, df.name as [FileName], df.type_desc as FileType, df.physical_name, fg.name as [FileGroup]
  FROM sys.database_files df
  JOIN sys.filegroups fg ON fg.data_space_id = df.data_space_id
  WHERE df.type_desc = 'ROWS'
    AND df.state_desc = 'ONLINE'
    AND fg.name NOT IN ('PRIMARY','KPI')
) f
ORDER BY [FileType] DESC, [FileGroup] DESC

--PRINT (@Script);
EXEC (@Script);

/*
    Release unused LOG space to the OS
*/
EXEC ('DBCC SHRINKFILE (2, TRUNCATEONLY)');
